// Picks one scenario per run. The scenario is the ground-truth label
// that the Python extractor reads back from the execution data.
const r = Math.random();
let scenario;
if (r < 0.80) scenario = 'normal';
else if (r < 0.87) scenario = 'slow';            // latency anomaly
else if (r < 0.92) scenario = 'hard_failure';    // step fails every attempt
else if (r < 0.97) scenario = 'flaky';           // step fails sometimes -> retries
else scenario = 'payload_spike';                 // unusual output volume

const rand = (min, max) => Math.round((min + Math.random() * (max - min)) * 100) / 100;

const delaySeconds = scenario === 'slow' ? rand(20, 45) : rand(1, 4);
const itemCount = scenario === 'payload_spike' ? Math.floor(rand(300, 600)) : Math.floor(rand(3, 8));

return [{
  json: {
    scenario,
    is_injected_anomaly: scenario !== 'normal',
    delaySeconds,
    itemCount,
    chosenAt: new Date().toISOString()
  }
}];

// Simulates an external tool/API call made by an AI agent step.
// Node settings: Retry On Fail = on, Max Tries = 3, Wait Between Tries = 2000 ms.
const input = $input.first().json;

if (input.scenario === 'hard_failure') {
  throw new Error('Simulated tool error: upstream service unavailable (HTTP 503)');
}
if (input.scenario === 'flaky' && Math.random() < 0.6) {
  throw new Error('Simulated transient error: request timeout');
}

return [{ json: { ...input, toolResponse: 'ok', toolFinishedAt: new Date().toISOString() } }];

// Simulates post-processing of the agent output.
const input = $input.first().json;
const out = [];
for (let i = 0; i < input.itemCount; i++) {
  out.push({ json: { scenario: input.scenario, index: i, value: Math.random() } });
}
return out;
